// 2026-05-16 SN2 fog descriptor-swap correlation state.
// 2026-05-17 REWRITE: was thread_local, but UE5's parallel rendering means
// RSSetViewports can fire on one translate thread while SetGraphicsRootDescriptorTable
// fires on another for the SAME command list. thread_local missed the viewport
// set (caused all `has_viewport=0` in earlier Path A test). Per-cmdlist map fixes this.
struct CommandListCorrelationState {
    using RootSlotArray = render::D3D12Diagnostics::RootSlotArray;
    using RootHashArray = render::D3D12Diagnostics::RootHashArray;
    static constexpr size_t MAX_ROOT_CONSTANT_DWORDS = 64;
    using RootConstantCountArray = std::array<uint8_t, render::D3D12Diagnostics::MAX_ROOT_BIND_SLOTS>;
    using RootConstantValuesArray = std::array<
        std::array<uint32_t, MAX_ROOT_CONSTANT_DWORDS>,
        render::D3D12Diagnostics::MAX_ROOT_BIND_SLOTS>;

    void*    current_pso = nullptr;
    void*    effective_pso = nullptr;
    float    viewport_top_left_x = 0.0f;
    float    viewport_top_left_y = 0.0f;
    float    viewport_width      = 0.0f;
    float    viewport_height     = 0.0f;
    bool     has_viewport        = false;
    D3D12_VIEWPORT viewport0{};
    UINT viewport_count = 0;
    D3D12_RECT scissor0{};
    UINT scissor_count = 0;
    bool has_scissor = false;
    D3D_PRIMITIVE_TOPOLOGY primitive_topology = D3D_PRIMITIVE_TOPOLOGY_UNDEFINED;
    bool has_primitive_topology = false;
    D3D12_INDEX_BUFFER_VIEW index_buffer_view{};
    bool has_index_buffer = false;
    static constexpr size_t MAX_TRACKED_VERTEX_BUFFERS = 16;
    std::array<D3D12_VERTEX_BUFFER_VIEW, MAX_TRACKED_VERTEX_BUFFERS> vertex_buffer_views{};
    std::array<bool, MAX_TRACKED_VERTEX_BUFFERS> has_vertex_buffer{};
    UINT max_vertex_buffer_slot = 0;
    std::array<ID3D12DescriptorHeap*, D3D12_DESCRIPTOR_HEAP_TYPE_NUM_TYPES> descriptor_heaps{};
    UINT descriptor_heap_count = 0;
    uintptr_t last_graphics_root_signature = 0;
    uintptr_t last_compute_root_signature = 0;
    // === Eye-Diff fingerprints (captured on bind, read at draw) ===
    StereoTraceBucket last_viewport_bucket = StereoTraceBucket::Unknown;
    uint64_t last_rtv0_handle = 0;                  // CPU descriptor handle of RTV slot 0
    std::array<uint64_t, 8> last_rtv_handles{};     // Full MRT array, slots 0..7 (0 means unbound)
    uint8_t last_rtv_count = 0;                     // Number of slots populated in last_rtv_handles
    uint64_t last_dsv_handle = 0;                   // CPU descriptor handle of DSV bound by last OMSetRenderTargets (0 = none)
    bool has_dsv = false;                           // Whether last OMSetRenderTargets supplied a DSV
    uint64_t last_graphics_root_desc_table0 = 0;    // GPU descriptor handle of root parameter 0 (graphics)
    RootSlotArray last_graphics_root_desc_tables{}; // Root descriptor-table GPU handles by root parameter index.
    RootSlotArray last_compute_root_desc_tables{};
    RootSlotArray last_graphics_root_cbv{};         // Root CBVs by root parameter index.
    RootSlotArray last_compute_root_cbv{};
    RootSlotArray last_graphics_root_srv{};
    RootSlotArray last_compute_root_srv{};
    RootSlotArray last_graphics_root_uav{};
    RootSlotArray last_compute_root_uav{};
    RootHashArray last_graphics_root_cbv_hash{};
    RootHashArray last_compute_root_cbv_hash{};
    RootHashArray last_graphics_root_constants_hash{};
    RootHashArray last_compute_root_constants_hash{};
    RootConstantCountArray last_graphics_root_constants_count{};
    RootConstantCountArray last_compute_root_constants_count{};
    RootConstantValuesArray last_graphics_root_constants{};
    RootConstantValuesArray last_compute_root_constants{};
    RootHashArray last_graphics_root_desc_table_resource_hash{};
    RootHashArray last_compute_root_desc_table_resource_hash{};
    std::vector<render::D3D12Diagnostics::DescriptorReadInfo> last_graphics_descriptor_reads{};
    std::vector<render::D3D12Diagnostics::DescriptorReadInfo> last_compute_descriptor_reads{};
    StereoTraceBucket last_scissor_bucket = StereoTraceBucket::Unknown;
    int last_known_eye_bucket = static_cast<int>(StereoTraceBucket::Unknown);
};
