// 2026-05-22: Magenta-PS debug-color override scope. Substitute the bound
// PSO with a magenta-output replacement around a single draw, then restore.
// Visualizes exactly which pixels a given PS touches.
struct Sn2DebugColorScope {
    bool active = false;
    ID3D12GraphicsCommandList* command_list = nullptr;
    ID3D12PipelineState* restore_pso = nullptr;

    Sn2DebugColorScope() = default;
    Sn2DebugColorScope(const Sn2DebugColorScope&) = delete;
    Sn2DebugColorScope& operator=(const Sn2DebugColorScope&) = delete;
    ~Sn2DebugColorScope() { restore(); }

    void restore() {
        if (!active) return;
        if (command_list != nullptr && restore_pso != nullptr) {
            command_list->SetPipelineState(restore_pso);
        }
        active = false;
    }
};

// 2026-05-22: Right-eye consumer SRV redirect. At right-eye draws of the SLW
// water-material PS (CRC 0x37558DE4), if the bound SRV table contains an SRV
// referencing a mirrored fog volume, substitute the slot with the mirror's SRV
// so the right eye reads its own (right-projected) fog data instead of the
// LEFT-projected original volume.
// 2026-05-22: Consumer CB swap. For the right-eye native draw of a configured
// PS CRC (default 0x37558DE4), substitute its bound CBV at a configured root
// with the LEFT-eye instance's CBV GPU_VA. The fog applier 0x37558DE4 fires
// natively on both eyes; CB-diff diagnostic showed RIGHT's root 3 has 3 slots
// (offset 768/784/800) ZEROED while LEFT has valid inverse-viewport scalars.
// Swapping to LEFT's CBV restores those values to RIGHT's sampler arithmetic.
//
// Since left + right of the same frame both bind from the same upload ring
// buffer, LEFT's GPU_VA points at LEFT's bytes for the duration of the frame
// (the ring doesn't wrap mid-frame in practice). No bytes copy required.
struct Sn2ConsumerCbSwapScope {
    bool active = false;
    ID3D12GraphicsCommandList* command_list = nullptr;
    UINT root_param = UINT_MAX;
    uint64_t restore_va = 0;

    Sn2ConsumerCbSwapScope() = default;
    Sn2ConsumerCbSwapScope(const Sn2ConsumerCbSwapScope&) = delete;
    Sn2ConsumerCbSwapScope& operator=(const Sn2ConsumerCbSwapScope&) = delete;
    ~Sn2ConsumerCbSwapScope() { restore(); }
    void restore() {
        if (!active) return;
        if (command_list != nullptr && root_param != UINT_MAX && restore_va != 0) {
            command_list->SetGraphicsRootConstantBufferView(
                root_param, static_cast<D3D12_GPU_VIRTUAL_ADDRESS>(restore_va));
        }
        active = false;
    }
};

// Captures last-seen LEFT-eye CBV GPU_VA at (PS CRC, root) and owns a small
// UEVR-side upload buffer used to build a partially-patched CB (RIGHT bytes
// with the 3 zeroed slots replaced by LEFT bytes). This preserves per-eye
// view fields (offsets 16/272/528 — different but valid between L/R) while
// fixing the missing inverse-viewport scalars (offsets 768/784/800).
struct Sn2ConsumerLeftCbSnapshot {
    std::mutex init_mu;
    std::atomic<uint64_t> last_left_va{0};
    Microsoft::WRL::ComPtr<ID3D12Resource> upload_buf;
    uint8_t* buf_cpu{nullptr};
    D3D12_GPU_VIRTUAL_ADDRESS buf_gpu{0};
    uint64_t buf_size{0};
    bool initialized{false};

    bool ensure(ID3D12Device* device, uint64_t size = 4096) {
        if (initialized) return true;
        std::scoped_lock _{init_mu};
        if (initialized) return true;
        if (device == nullptr) return false;
        D3D12_HEAP_PROPERTIES hp{};
        hp.Type = D3D12_HEAP_TYPE_UPLOAD;
        D3D12_RESOURCE_DESC rd{};
        rd.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
        rd.Width = size;
        rd.Height = 1;
        rd.DepthOrArraySize = 1;
        rd.MipLevels = 1;
        rd.SampleDesc.Count = 1;
        rd.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
        HRESULT hr = device->CreateCommittedResource(&hp, D3D12_HEAP_FLAG_NONE, &rd,
            D3D12_RESOURCE_STATE_GENERIC_READ, nullptr, IID_PPV_ARGS(&upload_buf));
        if (FAILED(hr) || upload_buf == nullptr) return false;
        D3D12_RANGE no_read{0, 0};
        void* mapped = nullptr;
        hr = upload_buf->Map(0, &no_read, &mapped);
        if (FAILED(hr) || mapped == nullptr) return false;
        buf_cpu = static_cast<uint8_t*>(mapped);
        std::memset(buf_cpu, 0, size);
        buf_gpu = upload_buf->GetGPUVirtualAddress();
        buf_size = size;
        initialized = true;
        SPDLOG_WARN("[SN2-ConsumerCbSwap] patch buffer ready cpu=0x{:x} gpu_va=0x{:x} size={}",
            reinterpret_cast<uintptr_t>(buf_cpu), buf_gpu, size);
        return true;
    }
};
inline Sn2ConsumerLeftCbSnapshot& consumer_left_cb_snapshot() {
    static Sn2ConsumerLeftCbSnapshot s;
    return s;
}

// SEH-guarded memcpy for upload-buffer reads (game may unmap mid-frame).
static bool sn2_consumer_safe_memcpy(void* dst, const void* src, size_t bytes) {
    __try {
        std::memcpy(dst, src, bytes);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

struct Sn2ConsumerSrvRedirectScope {
    bool active = false;
    ID3D12GraphicsCommandList* command_list = nullptr;
    UINT root_param = UINT_MAX;
    uint64_t restore_table_gpu = 0;

    Sn2ConsumerSrvRedirectScope() = default;
    Sn2ConsumerSrvRedirectScope(const Sn2ConsumerSrvRedirectScope&) = delete;
    Sn2ConsumerSrvRedirectScope& operator=(const Sn2ConsumerSrvRedirectScope&) = delete;
    ~Sn2ConsumerSrvRedirectScope() { restore(); }

    void restore() {
        if (!active) return;
        if (command_list != nullptr && root_param != UINT_MAX && restore_table_gpu != 0) {
            D3D12_GPU_DESCRIPTOR_HANDLE h{restore_table_gpu};
            command_list->SetGraphicsRootDescriptorTable(root_param, h);
        }
        active = false;
    }
};

// 2026-05-22: Multi-slot per-eye SRV pairing redirect (Sn2EyePairing). Restores
// up to 8 root descriptor tables that we swapped to scratch ranges. See
// Sn2EyePairingHook.hpp for the architecture.
struct Sn2EyePairingRedirectScope {
    bool active = false;
    ID3D12GraphicsCommandList* command_list = nullptr;
    ID3D12DescriptorHeap* restore_cbv_srv_uav_heap = nullptr;
    ID3D12DescriptorHeap* restore_sampler_heap = nullptr;
    bool restore_heaps = false;
    struct Entry { UINT root_param; uint64_t restore_table_gpu; };
    std::array<Entry, 64> entries{};
    size_t entry_count = 0;

    Sn2EyePairingRedirectScope() = default;
    Sn2EyePairingRedirectScope(const Sn2EyePairingRedirectScope&) = delete;
    Sn2EyePairingRedirectScope& operator=(const Sn2EyePairingRedirectScope&) = delete;
    ~Sn2EyePairingRedirectScope() { restore(); }

    void restore() {
        if (!active) return;
        if (command_list != nullptr) {
            if (restore_heaps && restore_cbv_srv_uav_heap != nullptr) {
                ID3D12DescriptorHeap* heaps[2]{restore_cbv_srv_uav_heap, restore_sampler_heap};
                const UINT heap_count = restore_sampler_heap != nullptr ? 2u : 1u;
                command_list->SetDescriptorHeaps(heap_count, heaps);
            }

            ++g_sn2_descriptor_table_rebind_depth;
            for (size_t i = 0; i < entry_count; ++i) {
                const auto& e = entries[i];
                if (e.restore_table_gpu == 0) continue;
                D3D12_GPU_DESCRIPTOR_HANDLE h{e.restore_table_gpu};
                command_list->SetGraphicsRootDescriptorTable(e.root_param, h);
            }
            --g_sn2_descriptor_table_rebind_depth;
        }
        active = false;
        entry_count = 0;
        restore_cbv_srv_uav_heap = nullptr;
        restore_sampler_heap = nullptr;
        restore_heaps = false;
    }
};

struct Sn2MirrorRtvRedirectScope {
    bool active = false;
    ID3D12GraphicsCommandList* command_list = nullptr;
    std::array<D3D12_CPU_DESCRIPTOR_HANDLE, 8> restore_rtvs{};
    UINT restore_rtv_count = 0;
    bool restore_has_dsv = false;
    D3D12_CPU_DESCRIPTOR_HANDLE restore_dsv{};

    Sn2MirrorRtvRedirectScope() = default;
    Sn2MirrorRtvRedirectScope(const Sn2MirrorRtvRedirectScope&) = delete;
    Sn2MirrorRtvRedirectScope& operator=(const Sn2MirrorRtvRedirectScope&) = delete;
    ~Sn2MirrorRtvRedirectScope() { restore(); }

    void restore() {
        if (!active) return;
        if (command_list != nullptr && restore_rtv_count > 0) {
            D3D12_CPU_DESCRIPTOR_HANDLE* dsv_ptr = restore_has_dsv ? &restore_dsv : nullptr;
            command_list->OMSetRenderTargets(restore_rtv_count, restore_rtvs.data(), FALSE, dsv_ptr);
        }
        active = false;
    }
};

